float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

// Türeve göre yumuşatılmış eşik (yalnız fragment'ta açılır): kenar net, tırtık yok.
#define AAW(x) max(abs(ddx(x)) + abs(ddy(x)), 0.0001)
#define AASTEP(edge, x) smoothstep((edge) - AAW(x), (edge) + AAW(x), (x))

code.fragment:
float4 frag(UPEInput i)
{
    float life = 1.0 - i.color.a;
    float u = i.uv.x;
    float v = i.uv.y - 0.5;
    float r = abs(v);
    // ön uç ömrün _Reveal kısmında 0'dan 1'e ilerler (dalgayla aynı hız)
    float front = saturate(life / _Reveal);
    float s = saturate(u / max(front, 0.001));
    float inLen = step(0.0, u) * (1.0 - AASTEP(front, u));
    // başta ve ön uçta incelir
    float taper = smoothstep(0.0, 0.12, u) * (1.0 - smoothstep(0.88, 1.0, s));
    float e = saturate((life - _ErodeStart) / max(1.0 - _ErodeStart, 0.001));
    // kalınlık boyunca fırça baskısı (düşük frekans) + kenarda kıl tırtığı (yüksek frekans, iki kenar ayrı)
    float press = vnoise(float2(u * _Fiber * 0.12, 3.7));
    float side = step(0.0, v);
    float jag = vnoise(float2(u * _Fiber * 0.45, side * 17.0 + 5.0));
    float hw = _Width * (0.25 + 0.75 * taper) * (0.7 + 0.6 * press) * (0.88 + 0.24 * jag) * (1.0 - e * 0.5);
    float rn = r / max(hw, 0.0005);
    float shp = (1.0 - AASTEP(1.0 + _InkWidth, rn)) * inLen;
    // kuru fırça: iz boyunca uzanan lif boşlukları (boyuna uzun, enine sık)
    float fib = vnoise(float2(u * _Fiber * 0.25, rn * 3.2 + side * 9.0));
    shp *= AASTEP(_Dry * (0.25 + 0.35 * (1.0 - taper)) * (0.4 + 0.6 * rn), fib);
    // baştan (u küçük) ön uca doğru erir
    shp *= AASTEP(e * 1.1, u * 0.7 + fib * 0.3);
    float bodyIn = 1.0 - AASTEP(1.0, rn);
    // çekirdek: kesikli düz çizgi değil; birbirinden bağımsız iki katmanda, başı dolgun ucu uzun sivri fırça vuruşları
    float sv = v / max(hw, 0.0005);
    float meander = (vnoise(float2(u * _Fiber * 0.05, 7.1)) - 0.5) * 0.8;
    float aw = AAW(sv);
    float wk = _CoreBand * (0.7 + 0.8 * smoothstep(0.6, 1.0, s));
    float uc1 = u * _Fiber * 0.075 + 0.9 * vnoise(float2(u * _Fiber * 0.03, 2.3));
    float id1 = floor(uc1);
    float t1 = frac(uc1) / (0.6 + 0.4 * hash21(float2(id1, 13.0)));
    float pr1 = 2.4 * pow(saturate(t1), 0.3) * pow(saturate(1.0 - t1), 1.4) * step(t1, 1.0);
    float of1 = meander + (hash21(float2(id1, 9.0)) - 0.5) * 0.45;
    float c1 = (1.0 - smoothstep(wk * pr1 - aw, wk * pr1 + aw, abs(sv - of1))) * step(0.22, hash21(float2(id1, 4.0)));
    float uc2 = u * _Fiber * 0.11 + 3.7 + 0.8 * vnoise(float2(u * _Fiber * 0.04, 5.9));
    float id2 = floor(uc2);
    float t2 = frac(uc2) / (0.5 + 0.4 * hash21(float2(id2, 31.0)));
    float pr2 = 2.4 * pow(saturate(t2), 0.3) * pow(saturate(1.0 - t2), 1.6) * step(t2, 1.0);
    float of2 = meander + (hash21(float2(id2, 17.0)) - 0.5) * 0.9;
    float c2 = (1.0 - smoothstep(wk * 0.5 * pr2 - aw, wk * 0.5 * pr2 + aw, abs(sv - of2))) * step(0.45, hash21(float2(id2, 23.0)));
    c1 *= step(aw * 0.55, wk * pr1);
    c2 *= step(aw * 0.55, wk * 0.5 * pr2);
    float coreIn = max(c1, c2) * bodyIn;
    float3 c = _InkColor.rgb;
    c = lerp(c, _BodyColor.rgb, bodyIn);
    c = lerp(c, _CoreColor.rgb, coreIn);
    c *= i.color.rgb;
    return float4(c, shp);
}
